  "measure_id": "SYN-0001",
  "restatements": [
    {
      "clause_id": "SYN-0001 §1",
      "text": "Requires individuals who keep a firearm in a residence to store it in a locked container when it is not being carried or used."
    },
    {
      "clause_id": "SYN-0001 §2",
      "text": "Directs the Department to issue a storage certificate to applicants who pay a $25 fee."
    },
    {
      "clause_id": "SYN-0001 §3",
      "text": "Preempts local governments from adopting or enforcing their own firearm storage ordinances, reserving that authority solely for the state."
    }
  ],
